# Bible People — life stories in order. Each card: short (swipe) + more (tap for the full story) + where to read it.
CATS = []
def cat(key, title, blurb, art, people): CATS.append({"key":key, "title":title, "blurb":blurb, "art":art, "people":people})
def C(h, t, more="", ref=None): return {"h":h, "t":t, "more":more, "ref":list(ref) if ref else None}

cat("twelve", "The 12 Disciples", "The ordinary men Jesus picked to change the world.", "last-supper", [
 dict(id="peter", name="Peter", role="Fisherman who became the leader of the apostles", art="peter-denies",
  facts=["Also called Simon", "Brother of Andrew", "Wrote 1 & 2 Peter"], cards=[
  C("A fisherman from Galilee", "Simon was a working fisherman on the Sea of Galilee, running boats with his brother Andrew and their partners James and John.",
    "Simon grew up in Bethsaida and later lived in Capernaum, a busy fishing town on the north shore of the Sea of Galilee. He was married — the Gospels mention his mother-in-law, whom Jesus healed of a fever in Simon’s own house. Fishing was hard, physical work done mostly at night with heavy nets. Simon was not a scholar or a priest; the religious leaders later called him “unschooled” and “ordinary.” His brother Andrew had been following John the Baptist, and Andrew was the one who first brought Simon to meet Jesus.", ("John",1)),
  C("A new name", "The first time Jesus looked at him, He said: “You are Simon — you will be called Cephas,” which means “rock.” In Greek, that’s Peter.",
    "Names mattered in the Bible. When God renamed someone — Abram to Abraham, Jacob to Israel — it marked a new identity and a new purpose. Jesus renamed Simon before he had done anything to earn it. “Cephas” is Aramaic for rock; “Petros” is the Greek form, which gives us Peter. It was a strange name for a man who would turn out to be impulsive and changeable. But Jesus was naming what He would make him, not what he already was.", ("John",1)),
  C("“Put out into deep water”", "After a night of catching nothing, Jesus told Peter to try again. The nets filled so full they began to tear. Peter fell at His knees.",
    "Jesus borrowed Peter’s boat as a floating stage to teach a crowd on the shore. Afterward He told Peter to row out and drop the nets. Peter, the professional, pushed back: “Master, we worked hard all night and caught nothing — but because You say so, I will.” The catch was so huge that two boats almost sank. Peter was suddenly terrified, not thrilled. He fell down and said, “Go away from me, Lord — I’m a sinful man.” Jesus answered, “Don’t be afraid. From now on you will catch people.” Peter, Andrew, James and John pulled the boats onto the shore, left everything, and followed Him.", ("Luke",5)),
  C("Walking on water", "In a storm at night, the disciples saw Jesus walking on the lake. Peter asked to come to Him, stepped out — and walked on water, until he looked at the waves.",
    "Jesus had sent the disciples across the lake while He prayed alone. Sometime between 3 and 6 a.m., battling a headwind, they saw a figure walking on the waves and screamed, thinking it was a ghost. Jesus called out, “Take courage! It is I. Don’t be afraid.” Peter said, “Lord, if it’s You, tell me to come to You on the water.” Jesus said, “Come.” Peter climbed out and actually walked toward Jesus. Then he noticed the wind, panicked, and started to sink, crying, “Lord, save me!” Jesus immediately grabbed his hand: “You of little faith, why did you doubt?” When they got into the boat, the wind stopped, and the disciples worshiped Him, saying, “Truly You are the Son of God.”", ("Matthew",14)),
  C("“You are the Messiah”", "Jesus asked, “Who do you say I am?” Peter answered first: “You are the Messiah, the Son of the living God.”",
    "Near the city of Caesarea Philippi, Jesus asked His disciples what people were saying about Him. Some said John the Baptist come back to life, others Elijah or Jeremiah. Then He made it personal: “But who do you say I am?” Peter answered, “You are the Christ, the Son of the living God.” Jesus told him this hadn’t come from human reasoning but was revealed by the Father, and said, “You are Peter, and on this rock I will build My church.” Minutes later, when Jesus explained He would suffer and be killed, Peter pulled Him aside to argue — and Jesus rebuked him sharply: “Get behind Me, Satan! You’re thinking like a human, not like God.” Peter could go from great insight to great mistake in a single conversation.", ("Matthew",16)),
  C("On the mountain", "Peter saw Jesus shine like the sun, with Moses and Elijah beside Him. Not knowing what to say, he offered to build three tents.",
    "Jesus took Peter, James and John up a high mountain. There His face shone like the sun and His clothes became dazzling white. Moses and Elijah — the great lawgiver and the great prophet — appeared and talked with Him about His coming death in Jerusalem. Peter, overwhelmed, blurted out an offer to put up three shelters, one for each of them. While he was still speaking, a bright cloud covered them and God’s voice said, “This is My Son, whom I love. Listen to Him!” The disciples fell face down, terrified, until Jesus touched them and said, “Get up. Don’t be afraid.” Years later Peter wrote about it: “We were eyewitnesses of His majesty.”", ("Matthew",17)),
  C("The foot washing", "At the Last Supper, Jesus knelt to wash His disciples’ feet. Peter refused — then asked Him to wash his hands and head too.",
    "Washing feet was a servant’s job. At the Passover meal, Jesus took off His outer robe, wrapped a towel around His waist and began washing the disciples’ dusty feet. When He came to Peter, Peter protested: “You will never wash my feet!” Jesus answered, “Unless I wash you, you have no part with Me.” Peter swung all the way the other direction: “Then not just my feet, Lord, but my hands and my head as well!” Jesus explained that He was showing them how to serve one another. That same night Peter promised, “Even if everyone else falls away, I never will. I’ll go to prison and die with You.” Jesus told him that before the rooster crowed, he would deny Him three times.", ("John",13)),
  C("The sword in the garden", "When soldiers came to arrest Jesus, Peter pulled a sword and cut off a servant’s ear. Jesus told him to put it away — and healed the ear.",
    "In Gethsemane, Jesus asked Peter, James and John to stay awake and pray with Him. Three times He came back and found them asleep. Then Judas arrived with a crowd carrying swords, clubs and torches. Peter drew a sword and struck Malchus, the high priest’s servant, cutting off his right ear. Jesus said, “Put your sword away! Shall I not drink the cup the Father has given Me?” Luke, who was a doctor, notes that Jesus touched the man’s ear and healed it. Then the disciples all ran.", ("John",18)),
  C("Three denials", "In the high priest’s courtyard, Peter was asked three times if he knew Jesus. Three times he said no. The rooster crowed, and Jesus looked at him.",
    "Peter followed at a distance and slipped into the courtyard of the high priest’s house, warming himself by a fire while Jesus was on trial inside. A servant girl looked at him: “You were with Him.” Peter said, “Woman, I don’t know Him.” Later someone else said, “You’re one of them.” “Man, I am not!” About an hour later another insisted, “Your Galilean accent gives you away.” Peter began to call down curses on himself and swore, “I don’t know the man!” Right then the rooster crowed. Luke records that Jesus turned and looked straight at Peter. Peter remembered what Jesus had said, went outside, and wept bitterly.", ("Luke",22)),
  C("Running to the tomb", "On Sunday morning, when Mary Magdalene said the tomb was empty, Peter ran to see. He went inside and found only the grave cloths.",
    "Peter had not been at the cross. Early on the first day of the week, Mary Magdalene came running: the stone was rolled away and the body was gone. Peter and John raced to the tomb. John got there first but stopped at the entrance; Peter barged straight in. He saw the linen strips lying there and the cloth that had been around Jesus’ head folded up by itself. Luke says he went home wondering what had happened. That same day the risen Jesus appeared to Peter personally — Paul and Luke both mention it — though no one recorded what was said.", ("John",20)),
  C("“Do you love me?”", "By the lake, the risen Jesus asked Peter three times, “Do you love Me?” — one for each denial. Each time: “Feed My sheep.”",
    "Some disciples went back to fishing in Galilee and caught nothing all night. At dawn a man on the shore told them to throw the net on the right side, and it filled with 153 large fish. John said, “It’s the Lord!” Peter jumped into the water and swam to shore. Jesus had a charcoal fire going with fish and bread — the same kind of fire Peter had stood beside when he denied Him. After breakfast Jesus asked, “Simon son of John, do you love Me?” three times. Peter was hurt by the third question, and said, “Lord, You know everything; You know I love You.” Each time Jesus gave him a job: “Feed My lambs… take care of My sheep.” Then He told Peter that one day he too would be led where he didn’t want to go — a hint of how he would die — and said, “Follow Me.”", ("John",21)),
  C("Pentecost", "Fifty days after Easter, the Holy Spirit came. Peter — who had been afraid of a servant girl — preached to thousands, and 3,000 were baptized.",
    "The disciples were gathered in Jerusalem during the feast of Pentecost when a sound like a rushing wind filled the house and something like tongues of fire rested on each of them. They began speaking in other languages, and pilgrims from all over the world heard them in their own language. Some mocked: “They’re drunk.” Peter stood up and said it was only nine in the morning — this was what the prophet Joel had promised. He told them plainly that the Jesus they had crucified, God had raised to life, and made Him both Lord and Messiah. The crowd was cut to the heart and asked what to do. Peter said, “Repent and be baptized, every one of you.” About 3,000 people were added that day.", ("Acts",2)),
  C("Healing and courage", "Peter healed a man born lame at the Temple gate, was arrested, and told the council: “We cannot stop speaking about what we have seen.”",
    "A man who had never walked sat begging at the Temple gate called Beautiful. Peter said, “I don’t have silver or gold, but what I have I give you: in the name of Jesus Christ of Nazareth, walk.” The man jumped up, walking and leaping and praising God. The crowd gathered and Peter preached again. The leaders arrested Peter and John and ordered them never to speak about Jesus. They noticed these were ordinary, uneducated men and realized they had been with Jesus. Peter answered, “Judge for yourselves whether it’s right to obey you rather than God. We cannot stop speaking about what we have seen and heard.” Later they were flogged — and left rejoicing that they had been counted worthy to suffer for His name.", ("Acts",3)),
  C("The door opened to everyone", "God sent Peter a vision and then to the home of a Roman officer, Cornelius. Peter realized the good news was for every nation.",
    "On a rooftop in Joppa, Peter saw a sheet lowered from heaven full of animals Jews were not allowed to eat, and a voice said, “Kill and eat.” Peter refused. The voice said, “Do not call anything impure that God has made clean.” Just then, messengers arrived from Cornelius, a Roman centurion who had been told by an angel to send for Peter. Jews did not normally enter a Gentile’s home, but Peter went. While he was speaking, the Holy Spirit came on everyone listening, and Peter had them baptized. It was a turning point: the church was no longer only for Jews.", ("Acts",10)),
  C("Freed by an angel", "King Herod jailed Peter to execute him. The night before, an angel woke him, his chains fell off, and he walked out.",
    "Herod Agrippa had just executed James, John’s brother, and arrested Peter during Passover, guarded by four squads of soldiers. The church prayed for him constantly. On the night before his trial, Peter was sleeping chained between two soldiers when an angel appeared, light filled the cell, and the angel struck his side: “Quick, get up!” The chains fell off. Peter thought he was dreaming as he followed the angel past two guard posts, and the iron gate to the city opened by itself. He went to the house of Mary, John Mark’s mother, where people were praying. A servant girl, Rhoda, was so excited to hear his voice that she left him standing at the door.", ("Acts",12)),
  C("How it ended", "Peter wrote two letters to suffering Christians. Early church writers report he was crucified in Rome under Emperor Nero, around AD 64–67.",
    "Peter’s two letters encourage believers facing persecution: “Cast all your anxiety on Him because He cares for you.” He calls himself a witness of Christ’s sufferings and an elder among elders. Jesus had told him he would “stretch out his hands” and be led where he did not want to go. Clement of Rome, writing about 30 years later, records that Peter was martyred. Later writers (Tertullian, Eusebius) place his death in Rome during Nero’s persecution, and tradition adds that he asked to be crucified upside down, not feeling worthy to die as Jesus did. St. Peter’s Basilica in Rome stands over the site traditionally held to be his grave.", ("1 Peter",5)),
 ]),
 dict(id="andrew", name="Andrew", role="The first disciple — the one who brought people to Jesus", art="fishers",
  facts=["Peter’s brother", "Fisherman", "Was a follower of John the Baptist"], cards=[
  C("A seeker", "Andrew was a fisherman from Bethsaida — and a follower of John the Baptist, looking for the Messiah.",
    "Andrew and his brother Simon Peter fished the Sea of Galilee. Unlike his brother, Andrew had already gone out to the Jordan River to hear John the Baptist preach repentance, and became one of John’s disciples. He was waiting and watching for the promised Messiah. His name is Greek, meaning “manly” or “brave.”", ("John",1)),
  C("The first to follow", "John pointed at Jesus and said, “Look, the Lamb of God!” Andrew followed Jesus and spent the whole day with Him.",
    "Andrew and another disciple heard John say this and immediately started following Jesus. Jesus turned and asked, “What are you looking for?” They asked where He was staying. He said, “Come and see.” They went and spent the rest of the day with Him — John even remembers it was about four in the afternoon. That makes Andrew one of the first two people ever to follow Jesus.", ("John",1)),
  C("“We found the Messiah!”", "The first thing Andrew did was find his brother Simon: “We have found the Messiah.” Then he brought him to Jesus.",
    "Andrew didn’t keep it to himself. He went straight to his brother and brought him to Jesus. That single introduction changed history — Simon became Peter, the leader of the apostles. Andrew is often listed in Peter’s shadow, but Peter was there because Andrew brought him.", ("John",1)),
  C("The boy’s lunch", "When 5,000 men needed food, Andrew found a boy with five barley loaves and two small fish. Jesus fed everyone with it.",
    "Jesus asked Philip where they could buy bread for the huge crowd. Philip did the math and said it was impossible. Andrew had found a boy with five small barley loaves and two fish, but added, “What are they among so many?” Jesus had everyone sit down, gave thanks, and passed out the food. Everyone ate as much as they wanted, and twelve baskets of leftovers were collected. Andrew didn’t see how it could work, but he brought what he found to Jesus anyway.", ("John",6)),
  C("Bringing the Greeks", "When some Greeks asked to see Jesus, Philip told Andrew, and together they brought them to Jesus.",
    "During Jesus’ last week in Jerusalem, some Greeks who had come to worship approached Philip and asked, “Sir, we want to see Jesus.” Philip told Andrew, and the two of them went to Jesus. It’s the third time John’s Gospel shows Andrew bringing someone to Jesus — his brother, a boy with a lunch, and now foreigners.", ("John",12)),
  C("How it ended", "Andrew was in the upper room at Pentecost. Tradition says he preached around the Black Sea and Greece and was crucified on an X-shaped cross in Patras.",
    "The Bible’s last mention of Andrew is in the list of apostles praying together in Jerusalem after Jesus ascended. Early church historians say he preached in Scythia (around the Black Sea) and Greece. Tradition holds that he was crucified at Patras, Greece, on an X-shaped cross, and that he preached to the crowd for two days while he was dying. The saltire (X) cross is called St. Andrew’s Cross and appears on the flag of Scotland, where he is the patron saint.", ("Acts",1)),
 ]),
 dict(id="james-zebedee", name="James", role="One of Jesus’ three closest friends — and the first apostle to die for Him", art="transfiguration",
  facts=["Son of Zebedee", "Brother of John", "“Son of Thunder”"], cards=[
  C("Leaving the boat", "James and John were mending nets with their father Zebedee when Jesus called them. They left the boat — and their father — and followed.",
    "Zebedee ran a fishing business on the Sea of Galilee with hired workers, so the family was fairly well off. Their mother, probably named Salome, later followed Jesus too and was at the cross. When Jesus called, James and his brother left immediately. James is always named before John in the early lists, so he was likely the older brother.", ("Mark",1)),
  C("Sons of Thunder", "Jesus nicknamed James and John “Boanerges” — Sons of Thunder. It fit.",
    "Jesus gave the brothers this nickname when He chose the twelve. We see why later: when a Samaritan village refused to welcome Jesus, James and John asked, “Lord, do You want us to call fire down from heaven to destroy them?” Jesus turned and rebuked them. They were passionate, loyal and quick to anger.", ("Luke",9)),
  C("The inner circle", "James was one of only three disciples Jesus took into His most private moments.",
    "Jesus took Peter, James and John with Him when He raised Jairus’s 12-year-old daughter from the dead, when He was transfigured in glory on the mountain, and deeper into the garden of Gethsemane to pray the night before He died. James saw both Jesus’ greatest glory and His deepest anguish.", ("Mark",5)),
  C("Asking for the best seats", "James and John asked to sit at Jesus’ right and left in His kingdom. Jesus asked: “Can you drink the cup I drink?”",
    "On the road to Jerusalem, the brothers (and in Matthew’s account, their mother) asked Jesus for the two top places of honor. The other ten disciples were angry. Jesus said they didn’t know what they were asking. “Can you drink the cup I drink?” They said, “We can.” Jesus told them they would. Then He taught all of them: whoever wants to be great must be the servant of all — “for even the Son of Man did not come to be served, but to serve, and to give His life as a ransom for many.”", ("Mark",10)),
  C("The first apostle to die", "About AD 44, King Herod Agrippa had James killed with the sword — the first of the twelve to be martyred.",
    "Acts records it in one sentence: Herod “had James, the brother of John, put to death with the sword.” Seeing that it pleased the people, Herod arrested Peter next. James was the only apostle whose martyrdom is recorded in the Bible. He drank the cup, just as Jesus had said. Spanish tradition holds that his remains rest at Santiago de Compostela, the destination of the famous pilgrimage route, the Camino de Santiago.", ("Acts",12)),
 ]),
 dict(id="john", name="John", role="“The disciple Jesus loved” — wrote the Gospel of John", art="patmos",
  facts=["Brother of James", "Took care of Mary", "Wrote 5 books of the Bible"], cards=[
  C("A young fisherman", "John was the son of Zebedee and brother of James, fishing the Sea of Galilee when Jesus called him.",
    "John was probably the youngest of the twelve. He may be the unnamed disciple who, with Andrew, first followed Jesus after John the Baptist pointed Him out. In his own Gospel he never uses his name, calling himself “the disciple whom Jesus loved.”", ("Mark",1)),
  C("A Son of Thunder", "Like his brother, John was fiery — he once wanted to call down fire on a village and tried to stop a stranger from healing in Jesus’ name.",
    "John told Jesus, “We saw someone driving out demons in Your name and we told him to stop, because he wasn’t one of us.” Jesus said, “Don’t stop him. Whoever is not against us is for us.” The same man who later wrote “God is love” started out with a hot temper.", ("Luke",9)),
  C("Close to Jesus", "At the Last Supper, John was reclining right next to Jesus. Peter signaled him to ask who the betrayer was.",
    "Jesus announced that one of the twelve would betray Him. Peter motioned to John, who was leaning against Jesus, to ask who. Jesus said it was the one to whom He would give a piece of bread dipped in the dish — and handed it to Judas. John was with Peter and James in Gethsemane, and later got into the high priest’s courtyard because he knew the high priest.", ("John",13)),
  C("At the cross", "John was the only one of the twelve at the cross. Jesus gave His mother to John: “Here is your mother.”",
    "Standing near the cross were Mary the mother of Jesus, her sister, Mary the wife of Clopas, Mary Magdalene — and John. Dying, Jesus saw His mother and John and said to her, “Woman, here is your son,” and to John, “Here is your mother.” From that hour John took her into his home. John also records details only an eyewitness would note: the soldiers gambling for the seamless robe, and blood and water flowing from Jesus’ side.", ("John",19)),
  C("He saw and believed", "On Easter morning John outran Peter to the tomb, saw the folded grave cloths, and believed.",
    "When Mary Magdalene reported the tomb empty, John and Peter ran. John arrived first, looked in and saw the linen lying there, but waited. After Peter went in, John went in too, and “he saw and believed.” A week later by the lake, it was John who first recognized the stranger on the shore: “It is the Lord!”", ("John",20)),
  C("A pillar of the church", "After Pentecost, John worked alongside Peter: healing a lame man, standing before the council, and going to Samaria.",
    "John and Peter were arrested together for preaching about Jesus. When the gospel spread to Samaria, the apostles sent Peter and John to pray for the new believers. Paul later called James (the brother of Jesus), Peter and John the “pillars” of the Jerusalem church.", ("Acts",4)),
  C("God is love", "John wrote the Gospel of John and three letters, full of one theme: God is love, so love one another.",
    "John’s Gospel opens, “In the beginning was the Word… and the Word became flesh,” and includes “For God so loved the world that He gave His only Son.” His first letter says, “God is love. Whoever lives in love lives in God.” He wrote so that readers would believe Jesus is the Christ, the Son of God, and have life in His name.", ("1 John",4)),
  C("Exile on Patmos", "In old age John was exiled to the island of Patmos, where he received the visions written in the Book of Revelation.",
    "The writer of Revelation calls himself John, a brother and companion in suffering, on Patmos “because of the word of God.” There he saw the risen Christ in blinding glory and was shown visions of heaven and the end of the age, ending with a new heaven and new earth where God wipes away every tear. Early writers say John lived to a very old age in Ephesus, the only apostle not killed for his faith. Jerome records that, when he was too frail to preach, he would only say: “Little children, love one another.”", ("Revelation",1)),
 ]),
 dict(id="philip", name="Philip", role="The disciple who said “Come and see”", art="multitude",
  facts=["From Bethsaida", "Brought Nathanael", "Practical thinker"], cards=[
  C("“Follow me”", "Jesus found Philip in Galilee and simply said, “Follow Me.” He was from Bethsaida, Peter and Andrew’s town.",
    "Philip is a Greek name, which may explain why Greek visitors later came to him first. John’s Gospel is the only one that tells us much about him.", ("John",1)),
  C("Come and see", "Philip told his friend Nathanael they’d found the Messiah. When Nathanael scoffed, Philip said, “Come and see.”",
    "Philip said, “We have found the one Moses wrote about in the Law, and the prophets also wrote about — Jesus of Nazareth, the son of Joseph.” Nathanael said, “Nazareth! Can anything good come from there?” Philip didn’t argue. He just invited him to meet Jesus for himself.", ("John",1)),
  C("The impossible math", "Facing 5,000 hungry men, Jesus asked Philip where to buy bread. Philip said eight months’ wages wouldn’t buy enough.",
    "John says Jesus asked only to test him; He already knew what He would do. Philip calculated that 200 denarii — about eight months of a laborer’s pay — wouldn’t buy enough for each person to get a bite. Then Jesus fed the whole crowd with five loaves and two fish.", ("John",6)),
  C("“Show us the Father”", "At the Last Supper Philip asked, “Lord, show us the Father.” Jesus answered, “Anyone who has seen Me has seen the Father.”",
    "Jesus had just said, “I am the way, the truth and the life. No one comes to the Father except through Me.” Philip asked to see the Father. Jesus replied, “Don’t you know Me, Philip, even after I have been among you such a long time? Anyone who has seen Me has seen the Father.”", ("John",14)),
  C("How it ended", "Philip was with the apostles at Pentecost. Early writers say he preached in Asia Minor and died in Hierapolis.",
    "Don’t confuse him with Philip the evangelist in Acts 8, a different man who was one of the seven deacons and baptized the Ethiopian official. Second-century writers say the apostle Philip died at Hierapolis in what is now Turkey. Archaeologists there have excavated a church built in his honor.", ("Acts",1)),
 ]),
 dict(id="bartholomew", name="Bartholomew (Nathanael)", role="The skeptic Jesus saw under the fig tree", art="sermon",
  facts=["Probably also called Nathanael", "Friend of Philip", "Honest to a fault"], cards=[
  C("Two names, one man", "Bartholomew is in every list of the twelve. Most scholars identify him with Nathanael, the friend Philip brought to Jesus.",
    "Bartholomew means “son of Tolmai” — a family name. Matthew, Mark and Luke always pair him with Philip; John never mentions Bartholomew but tells the story of Philip’s friend Nathanael (“gift of God”) from Cana. Putting those together, he is likely Nathanael Bar-Tolmai.", ("John",1)),
  C("“Anything good from Nazareth?”", "When Philip said the Messiah came from Nazareth, Nathanael scoffed. Nazareth was a tiny, unimpressive village.",
    "Nazareth had maybe a few hundred people and is never mentioned in the Old Testament. Nathanael was from Cana, a nearby town, so it might even have been a bit of local rivalry. He said what he thought.", ("John",1)),
  C("Under the fig tree", "Jesus greeted him: “A true Israelite, nothing false in him.” “How do You know me?” “I saw you under the fig tree.”",
    "Something about that detail stunned Nathanael — perhaps he had been praying there alone. He went from skeptic to believer in a moment: “Rabbi, You are the Son of God! You are the King of Israel!” Jesus told him he would see greater things: heaven opened and angels ascending and descending on the Son of Man — echoing Jacob’s ladder.", ("John",1)),
  C("How it ended", "He saw the risen Jesus at the lake. Tradition says he preached in India and Armenia and was martyred.",
    "Nathanael is named among those fishing with Peter when Jesus appeared on the shore and cooked them breakfast. Early church historian Eusebius reports he took the Gospel of Matthew to India. Armenian tradition says he was martyred there. He is often shown in art holding a knife, from the tradition that he was flayed.", ("John",21)),
 ]),
 dict(id="thomas", name="Thomas", role="“Doubting Thomas” — who ended up with the boldest confession", art=None,
  facts=["Called “the Twin”", "Brave and blunt", "Took the gospel to India"], cards=[
  C("The Twin", "Thomas was also called Didymus — Greek for “twin.” The Bible never says who his twin was.",
    "Thomas is in every list of the twelve, but only John’s Gospel tells us anything about his personality: blunt, loyal, and honest about what he didn’t understand.", ("John",11)),
  C("“Let us die with Him”", "When Jesus decided to return near Jerusalem, where people had tried to stone Him, Thomas said: “Let’s go too, so we may die with Him.”",
    "Lazarus had died in Bethany, two miles from Jerusalem. The disciples reminded Jesus that the leaders there had just tried to stone Him. Jesus was going anyway. Thomas spoke up: “Let us also go, that we may die with Him.” It’s grim, but it’s courage.", ("John",11)),
  C("“How can we know the way?”", "Jesus said, “You know the way to where I’m going.” Thomas said, “We don’t even know where You’re going.” Jesus: “I am the way.”",
    "At the Last Supper, Jesus spoke about preparing a place for them in His Father’s house. Thomas asked the honest question. The answer is one of Jesus’ most famous sayings: “I am the way and the truth and the life. No one comes to the Father except through Me.”", ("John",14)),
  C("The doubt", "Thomas missed Jesus’ first appearance. He said he wouldn’t believe unless he touched the nail wounds.",
    "On Easter evening Jesus appeared to the disciples behind locked doors — but Thomas wasn’t there. When they told him, he said, “Unless I see the nail marks in His hands and put my finger where the nails were, and put my hand into His side, I will not believe.”", ("John",20)),
  C("“My Lord and my God!”", "A week later Jesus appeared again and said, “Touch them.” Thomas said: “My Lord and my God!”",
    "The doors were locked again. Jesus stood among them and said to Thomas, “Put your finger here; see My hands. Reach out your hand and put it into My side. Stop doubting and believe.” Thomas answered with the clearest statement of who Jesus is in all the Gospels: “My Lord and my God!” Jesus said, “Because you have seen Me, you have believed; blessed are those who have not seen and yet have believed.”", ("John",20)),
  C("How it ended", "Ancient tradition says Thomas carried the gospel to India and was killed with a spear near Chennai around AD 72.",
    "The Christians of Kerala in southern India, called St. Thomas Christians, trace their church back to his preaching, and their tradition says he arrived in AD 52. He is said to have been martyred at a hill near Mylapore, Chennai, where the San Thome Basilica now stands over his traditional tomb.", ("John",21)),
 ]),
 dict(id="matthew", name="Matthew", role="Tax collector who walked away from the money", art="tribute",
  facts=["Also called Levi", "Worked for Rome", "Wrote the Gospel of Matthew"], cards=[
  C("A hated job", "Matthew, also called Levi, collected taxes in Capernaum for Herod and Rome. Tax collectors were seen as traitors and thieves.",
    "Tax collectors bought the right to collect taxes and kept whatever they charged above the required amount. Many got rich by overcharging their own people. Religious Jews treated them like prostitutes and outcasts. Matthew’s booth was on a busy trade road by the lake.", ("Matthew",9)),
  C("Two words", "Jesus walked by his booth and said, “Follow Me.” Matthew got up, left everything, and followed.",
    "Peter and Andrew could always go back to fishing. Matthew couldn’t get his job back once he walked away. Luke notes he “left everything.”", ("Luke",5)),
  C("The party", "Matthew threw a big dinner for Jesus and invited his tax-collector friends. The religious leaders were scandalized.",
    "The Pharisees asked the disciples, “Why does your teacher eat with tax collectors and sinners?” Jesus answered, “It is not the healthy who need a doctor, but the sick. I have not come to call the righteous, but sinners to repentance.” He told them to go learn what this means: “I desire mercy, not sacrifice.”", ("Matthew",9)),
  C("His Gospel", "The first book of the New Testament has been credited to Matthew since the early church. It shows how Jesus fulfilled the Old Testament.",
    "Papias, an early second-century bishop, said Matthew compiled the sayings of Jesus. Matthew’s Gospel quotes the Old Testament more than any other and repeatedly says “this was to fulfill what was spoken by the prophet.” It contains the Sermon on the Mount and ends with the Great Commission: “Go and make disciples of all nations.” Fittingly for a former tax man, it includes the most stories about money.", ("Matthew",28)),
  C("How it ended", "Matthew was with the apostles at Pentecost. Traditions differ on where he preached — Ethiopia, Persia or elsewhere — and how he died.",
    "The Bible doesn’t record Matthew’s later life. Various early traditions place his ministry in Judea, Ethiopia, or Persia, and most say he was martyred. His feast is celebrated on September 21 in the Western church.", ("Acts",1)),
 ]),
 dict(id="james-alphaeus", name="James, son of Alphaeus", role="The quiet apostle", art=None,
  facts=["Sometimes called “James the Less”", "Name in every list of the 12", "Almost nothing else is known"], cards=[
  C("Chosen", "Jesus prayed all night, then chose twelve apostles. James son of Alphaeus was one of them.",
    "Luke says Jesus spent the night on a mountain praying before choosing the twelve. This James is always ninth in the lists, called “son of Alphaeus” to distinguish him from James son of Zebedee.", ("Luke",6)),
  C("James the Less", "He may be the “James the younger” whose mother Mary stood watching at the cross.",
    "Mark names a woman at the cross as “Mary the mother of James the younger and of Joses.” Many identify this James with the son of Alphaeus. “The Less” likely meant younger or smaller in stature — not less important.", ("Mark",15)),
  C("There for everything", "Without a single recorded speech, he saw it all: the miracles, the cross, the risen Jesus, and Pentecost.",
    "He was among the twelve sent out to heal and preach, at the Last Supper, in the upper room after the resurrection, and praying when the Holy Spirit came. The Bible doesn’t record his death; traditions vary.", ("Acts",1)),
 ]),
 dict(id="jude-thaddaeus", name="Jude (Thaddaeus)", role="The apostle who asked one great question", art=None,
  facts=["Also called Thaddaeus", "Not Judas Iscariot", "Saint of “lost causes”"], cards=[
  C("Many names", "Matthew and Mark call him Thaddaeus; Luke calls him Judas son of James. John adds: “not Judas Iscariot.”",
    "After the betrayal, the name Judas carried a stain, which may be why some writers preferred Thaddaeus. He should not be confused with Jude the brother of Jesus, who wrote the short letter of Jude (though some traditions combine them).", ("Luke",6)),
  C("His question", "At the Last Supper he asked: “Why will You show Yourself to us and not to the world?”",
    "Jesus had said He would reveal Himself to those who love Him. Jude, perhaps expecting a public, kingly Messiah, asked why not to everyone. Jesus answered, “Anyone who loves Me will obey My teaching. My Father will love them, and We will come to them and make Our home with them.”", ("John",14)),
  C("How it ended", "Tradition says he preached in Mesopotamia and Persia with Simon the Zealot, and both were martyred there.",
    "Western tradition honors Jude and Simon together on October 28. Jude became known as the patron saint of desperate cases and lost causes — possibly because people avoided praying to someone named Judas, so he was the saint of last resort.", ("Acts",1)),
 ]),
 dict(id="simon-zealot", name="Simon the Zealot", role="A rebel who ended up on the same team as a tax collector", art=None,
  facts=["Called “the Zealot”", "Possibly anti-Rome", "Little else is known"], cards=[
  C("The Zealot", "He is always called “the Zealot” to tell him apart from Simon Peter. Zealots were passionate for God and often fiercely anti-Rome.",
    "Some Zealots later led a violent revolt against Rome (AD 66–70). Whether Simon belonged to that movement or was simply known for his zeal, the label suggests a man who wanted God’s kingdom to come by force.", ("Luke",6)),
  C("An unlikely team", "Jesus put Simon, who hated Rome, on the same team as Matthew, who had worked for it.",
    "In ordinary life these two might have been enemies. In Jesus’ company, they were brothers who ate, walked, prayed and preached together for three years.", ("Mark",3)),
  C("How it ended", "The Bible doesn’t say. Tradition says he preached with Jude in Persia and was martyred.",
    "Other traditions place him in Egypt or even Britain. He is commemorated with Jude on October 28.", ("Acts",1)),
 ]),
 dict(id="judas", name="Judas Iscariot", role="The disciple who betrayed Jesus", art="judas-kiss",
  facts=["Kept the money bag", "30 pieces of silver", "Betrayed Jesus with a kiss"], cards=[
  C("Chosen too", "Judas was one of the twelve. He was sent out to preach and heal like the others, and was trusted with the money.",
    "“Iscariot” may mean “man from Kerioth,” a town in Judea, which would make him the only one of the twelve not from Galilee. Every Gospel lists him last and adds “who betrayed Him.”", ("Matthew",10)),
  C("A thief", "John says Judas kept the money bag and used to help himself to what was put in it.",
    "When Mary of Bethany poured perfume worth a year’s wages on Jesus’ feet, Judas objected that it should have been sold and the money given to the poor. John adds that he said this “not because he cared about the poor but because he was a thief.”", ("John",12)),
  C("The deal", "Judas went to the chief priests: “What will you give me to hand Him over?” They counted out 30 pieces of silver.",
    "Thirty pieces of silver was the compensation price for a slave in the law of Moses, and the amount named in a prophecy of Zechariah. From then on, Judas watched for a chance to hand Jesus over away from the crowds.", ("Matthew",26)),
  C("The kiss", "In Gethsemane at night, Judas led soldiers to Jesus and identified Him with a kiss. Jesus said, “Judas, are you betraying Me with a kiss?”",
    "At the Last Supper Jesus had said one of them would betray Him, and gave Judas a piece of bread. John writes that Judas went out — “and it was night.” Hours later he arrived in the garden with a crowd armed with swords and clubs. Jesus called him “friend.”", ("Luke",22)),
  C("How it ended", "When Jesus was condemned, Judas regretted it, threw the silver into the Temple, and hanged himself.",
    "He told the priests, “I have sinned, for I have betrayed innocent blood.” They answered, “What is that to us?” The priests couldn’t put blood money in the treasury, so they bought a potter’s field to bury foreigners — called the Field of Blood. Peter and Judas both failed Jesus that night. Peter came back; Judas despaired.", ("Matthew",27)),
 ]),
 dict(id="matthias", name="Matthias", role="Chosen to replace Judas", art=None,
  facts=["The 13th apostle", "Picked by drawing lots", "Followed Jesus from the start"], cards=[
  C("A faithful follower", "Matthias wasn’t in the original twelve, but he followed Jesus the whole time — from John’s baptism to the ascension.",
    "Peter set the requirement: the replacement must have been with them the whole time Jesus went in and out among them, and be a witness of the resurrection. That means there were followers beyond the twelve who had been there from the start.", ("Acts",1)),
  C("Chosen", "The apostles proposed two men, prayed, and cast lots. The lot fell on Matthias.",
    "They prayed, “Lord, You know everyone’s heart. Show us which of these two You have chosen.” Casting lots was an Old Testament way of seeking God’s decision. This is the last time it’s used in the Bible — soon after, the Holy Spirit came at Pentecost. Tradition says Matthias later preached in Judea and beyond and was martyred.", ("Acts",1)),
 ]),
])
